const http = require('node:http');
const https = require('node:https');

const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');

const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};

const request = (urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        statusCode: res.statusCode || 0,
        body,
      });
    });
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
});

const parseJson = (value, fallback) => {
  try {
    return value ? JSON.parse(value) : fallback;
  } catch {
    return fallback;
  }
};

const statusResponse = await request(`${runnerBase}/repo/status`, { headers });
if (statusResponse.statusCode < 200 || statusResponse.statusCode >= 300) {
  throw new Error(`Runner repo status failed: ${statusResponse.statusCode} ${statusResponse.body}`);
}
const repoStatus = parseJson(statusResponse.body, {});

let action = 'noop';
let mode = 'sync';
let args = [];
let dedupeKey = '';
let reason = 'No action needed.';

if (repoStatus.branch === 'main') {
  reason = 'Repository is on main; supervisor only acts on feature branches.';
} else if (!repoStatus.clean) {
  reason = 'Working tree is not clean; refusing to publish or merge automatically.';
} else if (!repoStatus.pr && Number(repoStatus.aheadCount || 0) > 0) {
  action = 'pr_publish';
  args = [repoStatus.latestCommit || `chore: publish ${repoStatus.branch}`, repoStatus.latestCommit || `chore: publish ${repoStatus.branch}`];
  reason = 'Feature branch is ahead of main with no PR open, so publish the branch and create a PR.';
} else if (repoStatus.pr?.number) {
  action = 'pr_autofinish';
  mode = 'async';
  args = [String(repoStatus.pr.number)];
  dedupeKey = `pr-autofinish-${repoStatus.pr.number}`;
  reason = 'Open PR found; hand off review, settle-window, thread-resolution, and merge flow to pr-autofinish.';
} else {
  reason = 'Feature branch has no ahead commits and no open PR, so nothing is queued.';
}

let jobResult = null;
if (action !== 'noop') {
  const jobResponse = await request(`${runnerBase}/jobs`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ action, mode, args, dedupeKey }),
  });
  if (![200, 202].includes(jobResponse.statusCode)) {
    throw new Error(`Runner job failed: ${jobResponse.statusCode} ${jobResponse.body}`);
  }
  jobResult = parseJson(jobResponse.body, null);
}

const timestamp = new Date().toISOString().replace(/[:]/g, '-');
const safeBranch = String(repoStatus.branch || 'unknown').replace(/[^a-zA-Z0-9._-]+/g, '-');
const reportRelativePath = `github-pr-automation/${timestamp}-${safeBranch}.md`;
const reportContent = [
  '# GitHub PR Automation Supervisor',
  '',
  `Generated: ${new Date().toISOString()}`,
  `Branch: ${repoStatus.branch}`,
  `Working tree clean: ${repoStatus.clean}`,
  `Ahead of main: ${repoStatus.aheadCount}`,
  `Behind main: ${repoStatus.behindCount}`,
  '',
  '## Decision',
  '',
  `Action: ${action}`,
  reason,
  '',
  '## PR Context',
  '',
  repoStatus.pr ? `- PR #${repoStatus.pr.number}: ${repoStatus.pr.title} (${repoStatus.pr.url})` : '- No open PR detected for the current branch.',
  repoStatus.pr ? `- Review decision: ${repoStatus.pr.reviewDecision || 'none'}` : '',
  repoStatus.pr ? `- Merge state: ${repoStatus.pr.mergeStateStatus || 'unknown'}` : '',
  '',
  '## Job Result',
  '',
  jobResult ? '```json\n' + JSON.stringify(jobResult, null, 2) + '\n```' : 'No job was launched.',
].filter(Boolean).join('\n');

const writeResponse = await request(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (writeResponse.statusCode < 200 || writeResponse.statusCode >= 300) {
  throw new Error(`Runner report write failed: ${writeResponse.statusCode} ${writeResponse.body}`);
}

return [{
  json: {
    generatedAt: new Date().toISOString(),
    action,
    reason,
    reportRelativePath,
    repoStatus,
    jobResult,
  },
}];
